export type Subcategory = {
  nome: string;
  slug: string;
};

export type Categoria = {
  nome: string;
  slug: string;
  icone: string;
  subcategorias: Subcategory[];
};

export type Produto = {
  id: string;
  codigo: string;
  nome: string;
  categoria: string;
  subcategoria: string;
  descricao: string;
  preco: number;
  precoPromocional?: number;
  imagem?: string;
  disponivel: boolean;
  oferta: boolean;
  rasgaPreco?: boolean;
  informacoes?: string[];
  fabricante?: string;
  principioAtivo?: string;
  registroMs?: string;
  estoque?: number;
  unidade?: string;
};

export type Catalogo = {
  categorias: Categoria[];
  produtos: Produto[];
  vitrines?: {
    rasgaPreco: Produto[];
    ofertas: Produto[];
  };
};

